package org.studentdiscounts.submission.domain;

import com.fasterxml.uuid.Generators;
import com.fasterxml.uuid.impl.TimeBasedEpochRandomGenerator;
import java.security.SecureRandom;
import java.util.UUID;

/** UUIDv7 identifiers generated by Submission, never a restriction on external identifiers. */
public final class SubmissionIds {
  private static final TimeBasedEpochRandomGenerator GENERATOR =
      Generators.timeBasedEpochRandomGenerator(new SecureRandom());

  private SubmissionIds() {}

  public static UUID newId() {
    return GENERATOR.generate();
  }
}
